CREATE TABLE orders(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,order_number VARCHAR(64) NOT NULL,customer_id UUID NOT NULL,store_id UUID NOT NULL,status VARCHAR(32) NOT NULL,currency VARCHAR(3) NOT NULL,subtotal NUMERIC(19,4) NOT NULL CHECK(subtotal>=0),created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT uq_orders_tenant_number UNIQUE(tenant_id,order_number));
CREATE TABLE order_items(id UUID PRIMARY KEY,order_id UUID NOT NULL REFERENCES orders(id),tenant_id UUID NOT NULL,sellable_product_id UUID NOT NULL,product_snapshot TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),unit_price NUMERIC(19,4) NOT NULL CHECK(unit_price>=0),subtotal NUMERIC(19,4) NOT NULL CHECK(subtotal>=0),currency VARCHAR(3) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX idx_orders_tenant_customer ON orders(tenant_id,customer_id);CREATE INDEX idx_orders_tenant_store ON orders(tenant_id,store_id);CREATE INDEX idx_order_items_tenant_order ON order_items(tenant_id,order_id);
